export type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export interface Slot {
  startsAt: string;
  endsAt: string;
}

export const OPEN_HOUR = 8;
export const CLOSE_HOUR = 20;

const HOUR_MS = 3600000;

/** Valide le parametre de date et renvoie le jour normalise au format YYYY-MM-DD. */
export function parseDay(date: unknown): Result<string> {
  if (typeof date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    return { ok: false, error: "date invalide, format attendu YYYY-MM-DD" };
  }
  const parsed = new Date(`${date}T00:00:00.000Z`);
  if (Number.isNaN(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== date) {
    return { ok: false, error: "date inexistante" };
  }
  return { ok: true, value: date };
}

/** Calcule les creneaux libres d'un jour UTC entre les heures d'ouverture, a partir des reservations. */
export function freeSlots(date: string, booked: Slot[]): Slot[] {
  const dayStart = Date.parse(`${date}T00:00:00.000Z`);
  const open = dayStart + OPEN_HOUR * HOUR_MS;
  const close = dayStart + CLOSE_HOUR * HOUR_MS;

  const intervals = booked
    .map((b) => ({
      start: Math.max(Date.parse(b.startsAt), open),
      end: Math.min(Date.parse(b.endsAt), close)
    }))
    .filter((i) => i.start < i.end)
    .sort((a, b) => a.start - b.start);

  const free: Slot[] = [];
  let cursor = open;
  for (const i of intervals) {
    if (i.start > cursor) {
      free.push({
        startsAt: new Date(cursor).toISOString(),
        endsAt: new Date(i.start).toISOString()
      });
    }
    cursor = Math.max(cursor, i.end);
  }
  if (cursor < close) {
    free.push({
      startsAt: new Date(cursor).toISOString(),
      endsAt: new Date(close).toISOString()
    });
  }
  return free;
}

export default freeSlots;

import { describe, it, expect } from "vitest";
import { freeSlots, parseDay } from "../src/lib/availability.js";

const DAY = "2026-10-05";
const at = (hhmm: string, day = DAY) => `${day}T${hhmm}:00.000Z`;
const slot = (from: string, to: string) => ({ startsAt: at(from), endsAt: at(to) });

describe("freeSlots", () => {
  it("renvoie un seul creneau 08-20 pour un jour vide", () => {
    expect(freeSlots(DAY, [])).toEqual([slot("08:00", "20:00")]);
  });

  it("coupe en deux autour d'une reservation au milieu", () => {
    expect(freeSlots(DAY, [slot("09:00", "11:00")])).toEqual([
      slot("08:00", "09:00"),
      slot("11:00", "20:00")
    ]);
  });

  it("fusionne les reservations qui se touchent sans creneau de longueur nulle", () => {
    expect(freeSlots(DAY, [slot("10:00", "11:00"), slot("09:00", "10:00")])).toEqual([
      slot("08:00", "09:00"),
      slot("11:00", "20:00")
    ]);
  });

  it("gere les reservations collees a l'ouverture et a la fermeture", () => {
    expect(freeSlots(DAY, [slot("08:00", "09:00"), slot("19:00", "20:00")])).toEqual([
      slot("09:00", "19:00")
    ]);
  });

  it("tronque une reservation qui chevauche minuit", () => {
    const before = { startsAt: at("22:00", "2026-10-04"), endsAt: at("09:00") };
    const after = { startsAt: at("18:00"), endsAt: at("04:00", "2026-10-06") };
    expect(freeSlots(DAY, [before, after])).toEqual([slot("09:00", "18:00")]);
  });

  it("ignore une reservation d'un autre jour", () => {
    const other = { startsAt: at("09:00", "2026-10-06"), endsAt: at("11:00", "2026-10-06") };
    expect(freeSlots(DAY, [other])).toEqual([slot("08:00", "20:00")]);
  });

  it("renvoie une liste vide pour un jour complet", () => {
    expect(freeSlots(DAY, [slot("07:00", "21:00")])).toEqual([]);
  });

  it("fusionne les reservations imbriquees", () => {
    expect(freeSlots(DAY, [slot("09:00", "15:00"), slot("10:00", "11:00")])).toEqual([
      slot("08:00", "09:00"),
      slot("15:00", "20:00")
    ]);
  });
});

describe("parseDay", () => {
  it("accepte une date valide", () => {
    expect(parseDay("2026-10-05")).toEqual({ ok: true, value: "2026-10-05" });
  });

  it.each([undefined, "2026-1-5", "2026-02-30", "abc"])("refuse %s", (input) => {
    expect(parseDay(input).ok).toBe(false);
  });
});

